import React from 'react';
import Slider from 'react-slick';
import './Works.css';

const Works = () => {
    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        arrows: false
    };

    // Manually specify each image path
    const projectImages = [
        '/img/graphicverse/01.jpg',
        + '/img/graphicverse/02.jpg',
        + '/img/graphicverse/03.jpg',
        + '/img/graphicverse/04.jpg',
        + '/img/graphicverse/05.jpg',
    ];

    return (
        <section id="works">
            <div className="content">
                <div className="text-container">
                    <h1>My Previous Projects</h1>
                </div>
                <div className="carousel-container">
                    <Slider {...settings}>
                        {projectImages.map((image, index) => (
                            <div key={index}>
                                <img src={image} alt={`Project ${index + 1}`} />
                            </div>
                        ))}
                    </Slider>
                </div>
            </div>
        </section>
    );
};

export default Works;
